style.css:
@-moz-document url-prefix("https://www.bandlab.com/studio?id=c2c3be26-40bc-f011-8196-0022484a3197") {
:root {
  }

  .studio img, main img, .hero img {
    visibility: hidden !important;
  }

  .studio, main, .hero {
    position: relative !important;
  }

  .studio::before, main::before, .hero::before {
    content: "" !important;
    position: absolute;
    top: 20px;
    left: 20px;
    width: calc(100% - 40px);
    height: 60vh;
    background-image: var(--MY_IMG);
    background-size: cover;
    background-position: center;
    border: 14px solid #fff; /* cornice bianca stile polaroid */
    border-bottom-width: 54px;
    border-radius: 8px;
    box-shadow: 0 14px 30px rgba(0,0,0,0.5);
    filter: sepia(0.2) contrast(1.05) brightness(0.95) saturate(1.1);
    z-index: 9999;
    pointer-events: none;
  }

  .studio::after, main::after, .hero::after {
    content: var(--CAPTION);
    position: absolute;
    bottom: 40px;
    left: 0;
    width: 100%;
    text-align: center;
    font-family: "Courier New", monospace;
    color: #444;
    font-size: 14px;
    letter-spacing: 0.5px;
    text-shadow: 0 1px 2px rgba(255,255,255,0.6);
    z-index: 10000;
  }
}
